let CURRENT_LANG = localStorage.getItem("hmda-lang") || "en";

function t(key) {
  const dict = I18N[CURRENT_LANG] || I18N.en;
  return dict[key] ?? I18N.en[key] ?? key;
}

/* t() + {placeholder} substitution, for narrative sentences with embedded numbers
   (e.g. "{n} applications in the full file"). vars values are inserted as-is (HTML
   already formatted by the caller, e.g. "<b>16.08M</b>"), not escaped. */
function tf(key, vars) {
  let s = t(key);
  if (vars) for (const k in vars) s = s.split(`{${k}}`).join(vars[k]);
  return s;
}

/* Walks every [data-i18n] (textContent) and [data-i18n-html] (innerHTML,
   for strings with <b>/<code>/<i> markup) element and applies the current
   language. Call once on load and again after every language switch. */
function applyStaticI18n(root) {
  (root || document).querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.getAttribute("data-i18n"));
  });
  (root || document).querySelectorAll("[data-i18n-html]").forEach((el) => {
    el.innerHTML = t(el.getAttribute("data-i18n-html"));
  });
  (root || document).querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    el.placeholder = t(el.getAttribute("data-i18n-placeholder"));
  });
  (root || document).querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.title = t(el.getAttribute("data-i18n-title"));
  });
  document.documentElement.lang = CURRENT_LANG;
}

function setLang(lang) {
  CURRENT_LANG = lang;
  localStorage.setItem("hmda-lang", lang);
  applyStaticI18n();
  if (typeof syncLangToggle === "function") syncLangToggle();
  if (typeof renderStatStrip === "function") renderStatStrip();
  if (typeof RENDERERS !== "undefined" && typeof activeTab !== "undefined") {
    document.getElementById("page-title").textContent = t(PAGE_META[activeTab][0]);
    if (typeof withLoading === "function") withLoading(() => RENDERERS[activeTab]());
    else RENDERERS[activeTab]();
  }
}
